SELECT n.n_name, YEAR(o.o_orderdate) AS o_year, SUM(l.l_extendedprice*(1-l.l_discount)-ps.ps_supplycost*l.l_quantity) AS sum_profit FROM tpch_part p JOIN tpch_lineitem l ON p.p_partkey=l.l_partkey JOIN tpch_partsupp ps ON ps.ps_partkey=l.l_partkey AND ps.ps_suppkey=l.l_suppkey JOIN tpch_orders o ON o.o_orderkey=l.l_orderkey JOIN tpch_supplier s ON s.s_suppkey=l.l_suppkey JOIN tpch_nation n ON n.n_nationkey=s.s_nationkey WHERE p.p_name LIKE '%green%' GROUP BY n.n_name, YEAR(o.o_orderdate) ORDER BY n.n_name, o_year DESC;
